INSERT INTO public.cbt_questions (id, type, subject, text, media_type, media_url, options, pairs, answer, weight, explanation) VALUES
  ('Q_20261102_01', 'PG', 'IPAS', 'Salah satu sifat cahaya adalah…', 'none', '', '["Merambat berbelok-belok", "Merambat lurus", "Tidak dapat dipantulkan", "Hanya merambat dalam air"]'::jsonb, '[]'::jsonb, 'Merambat lurus', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_02', 'PG', 'IPAS', 'Kita dapat melihat benda karena cahaya…', 'none', '', '["Masuk ke mata setelah dipantulkan oleh benda", "Berhenti di permukaan benda", "Berubah menjadi bunyi", "Selalu menembus semua benda"]'::jsonb, '[]'::jsonb, 'Berhenti di permukaan benda', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_03', 'PG', 'IPAS', 'Bayangan terbentuk di belakang tubuh ketika kita berdiri dibawah sinar matahari karena cahaya…', 'none', '', '["Dapat merambat lurus dan terhalang benda", "Selalu menembus benda gelap", "Berubah menjadi panas saja", "Tidak dapat bergerak"]'::jsonb, '[]'::jsonb, 'Selalu menembus benda gelap', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_04', 'PG', 'IPAS', 'Spion kendaraan menggunakan cermin cembung karena cermin ini…', 'none', '', '["Memperbesar bayangan selalu", "Memiliki bidang pandang lebih luas", "Menghasilkan bayangan terbalik selalu", "Menyerap cahaya"]'::jsonb, '[]'::jsonb, 'Memiliki bidang pandang lebih luas', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_05', 'PG', 'IPAS', 'Cermin cekung dapat dimanfaatkan pada…', 'none', '', '["Spion kendaraan", "Kacamata untuk penderita rabun jauh (miopi)", "Kaca jendela bening", "Layar televisi"]'::jsonb, '[]'::jsonb, 'Kacamata untuk penderita rabun jauh (miopi)', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_06', 'PG', 'IPAS', 'Bagian mata yang memberi warna pada mata dan mengatur besar kecilnya pupil adalah…', 'none', '', '["Retina", "Iris", "Saraf mata", "Kornea"]'::jsonb, '[]'::jsonb, 'Iris', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_07', 'PG', 'IPAS', 'Pupil berfungsi untuk…', 'none', '', '["Mengatur jumlah cahaya yang masuk ke mata", "Menghasilkan air mata", "Meneruskan bunyi ke otak", "Menggerakkan kelopak mata"]'::jsonb, '[]'::jsonb, 'Menghasilkan air mata', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_08', 'PG', 'IPAS', 'Lensa mata membantu…', 'none', '', '["Memfokuskan cahaya agar bayangan jatuh pada retina", "Melindungi telinga dari bunyi", "Mengatur warna rambut", "Menghasilkan cahaya sendiri"]'::jsonb, '[]'::jsonb, 'Melindungi telinga dari bunyi', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_09', 'PG', 'IPAS', 'Bagian bening di bagian depan mata yang membantu membiaskan cahaya adalah…', 'none', '', '["Kornea", "Retina", "Saraf optik", "Iris"]'::jsonb, '[]'::jsonb, 'Retina', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_10', 'PG', 'IPAS', 'Seseorang dapat melihat benda dekat dengan jelas, tetapi benda jauh tampak kabur. Gangguan ini disebut…', 'none', '', '["Rabun dekat (hipermetropi)", "Rabun jauh (miopi)", "Buta warna", "Presbiopi"]'::jsonb, '[]'::jsonb, 'Rabun jauh (miopi)', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_11', 'PG', 'IPAS', 'Gangguan penglihatan yang menyebabkan seseorang sulit melihat benda dekat disebut…', 'none', '', '["Miopi", "Hipermetropi", "Buta warna", "Rabun senja"]'::jsonb, '[]'::jsonb, 'Hipermetropi', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_12', 'PG', 'IPAS', 'Kebiasaan yang baik untuk menjaga kesehatan mata adalah…', 'none', '', '["Membaca ditempat gelap", "Menatap layar dari jarak yang sangat dekat", "Membaca dengan pencahayaan cukup", "Mengucek mata dengan tangan kotor"]'::jsonb, '[]'::jsonb, 'Menatap layar dari jarak yang sangat dekat', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_13', 'PG', 'IPAS', 'Bunyi dihasilkan oleh benda yang…', 'none', '', '["Bergetar", "Diam", "Membeku", "Memantulkan cahaya"]'::jsonb, '[]'::jsonb, 'Diam', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_14', 'PG', 'IPAS', 'Bunyi dapat merambat melalui…', 'none', '', '["Ruang hampa saja", "Benda padat, cair dan gas", "Cahaya saja", "Ruang kosong tanpa zat perantara"]'::jsonb, '[]'::jsonb, 'Benda padat, cair dan gas', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_15', 'PG', 'IPAS', 'Saat menempelkan telinga pada meja, ketukan di ujung meja dapat terdengar karena bunyi merambat melalui…', 'none', '', '["Benda padat", "Ruang hampa", "Cahaya", "Bayangan"]'::jsonb, '[]'::jsonb, 'Ruang hampa', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_16', 'PG', 'IPAS', 'Hewan yang memakan tumbuhan disebut herbivora. Berikut ini yang termasuk hewan herbivora adalah ....', 'none', '', '["Harimau", "Kambing", "Elang", "Ular"]'::jsonb, '[]'::jsonb, 'Kambing', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_17', 'PG', 'IPAS', 'Hewan yang memperoleh makanan dengan memangsa hewan lain adalah ....', 'none', '', '["Sapi", "Kelinci", "Singa", "Kambing"]'::jsonb, '[]'::jsonb, 'Kelinci', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_18', 'PG', 'IPAS', 'Dalam rantai makanan, tumbuhan hijau disebut produsen karena ....', 'none', '', '["Memakan hewan lain", "Dapat membuat makanan sendiri", "Menguraikan bangkai hewan", "Selalu hidup di dalam tanah"]'::jsonb, '[]'::jsonb, 'Dapat membuat makanan sendiri', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_19', 'PG', 'IPAS', 'Berikut ini yang termasuk makhluk hidup sebagai konsumen adalah ....', 'none', '', '["Rumput", "Padi", "Pohon mangga", "Belalang"]'::jsonb, '[]'::jsonb, 'Padi', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_20', 'PG', 'IPAS', 'Jamur dan bakteri memiliki peran penting dalam ekosistem, yaitu sebagai ....', 'none', '', '["Produsen", "Konsumen tingkat pertama", "Dekomposer", "Pemangsa"]'::jsonb, '[]'::jsonb, 'Konsumen tingkat pertama', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_21', 'PG', 'IPAS', 'Perhatikan ilustrasi berikut!<br>Seekor kelinci sedang memakan rumput. Berdasarkan gambar tersebut, kelinci termasuk hewan ....', 'image', './assets/soal/soal-0001.jpg', '["Herbivora", "Karnivora", "Omnivora", "Dekomposer"]'::jsonb, '[]'::jsonb, 'Karnivora', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_22', 'PG', 'IPAS', 'Di sebuah sawah terdapat padi, belalang, katak, dan ular. Makhluk hidup yang berperan sebagai produsen adalah ....', 'none', '', '["Katak", "Ular", "Belalang", "Padi"]'::jsonb, '[]'::jsonb, 'Ular', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_23', 'PG', 'IPAS', 'Perhatikan makhluk hidup berikut!<br>Belalang memakan daun tumbuhan untuk memperoleh energi. Dalam rantai makanan, belalang berperan sebagai ....', 'image', './assets/soal/soal-0002.jpg', '["Produsen", "Konsumen tingkat pertama", "Dekomposer", "Pengurai"]'::jsonb, '[]'::jsonb, 'Konsumen tingkat pertama', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_24', 'PG', 'IPAS', 'Perhatikan makhluk hidup berikut:<br>Urutan rantai makanan yang benar adalah ....', 'none', '', '["Padi", "Tikus", "Ular", "Elang"]'::jsonb, '[]'::jsonb, 'Tikus', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_25', 'PG', 'IPAS', 'Dalam rantai makanan: rumput → belalang → katak → ular, makhluk hidup yang dimakan oleh katak adalah ....', 'none', '', '["Rumput", "Belalang", "Ular", "Jamur"]'::jsonb, '[]'::jsonb, 'Belalang', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_26', 'PG', 'IPAS', 'Di suatu padang rumput terjadi kekeringan sehingga jumlah rumput berkurang drastis. Di tempat tersebut terdapat belalang yang memakan rumput dan katak yang memakan belalang.<br>Apa kemungkinan yang terjadi jika rumput semakin sedikit?', 'none', '', '["Jumlah belalang dapat menurun karena kekurangan makanan.", "Jumlah belalang pasti bertambah banyak.", "Jumlah katak tidak akan terpengaruh.", "Semua hewan berubah menjadi produsen."]'::jsonb, '[]'::jsonb, 'Jumlah belalang pasti bertambah banyak.', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_27', 'PG', 'IPAS', 'Perhatikan rantai makanan berikut!<br>Rumput → Belalang → Katak → Ular → Elang<br>Jika jumlah katak berkurang secara drastis, kemungkinan yang terjadi adalah ....', 'image', './assets/soal/soal-0003.jpg', '["Jumlah belalang dapat meningkat.", "Jumlah rumput langsung habis karena dimakan ular.", "Jumlah belalang pasti menghilang.", "Jumlah rumput tidak mungkin berubah."]'::jsonb, '[]'::jsonb, 'Jumlah rumput langsung habis karena dimakan ular.', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_28', 'PG', 'IPAS', 'Bayangkan dalam suatu lingkungan tidak terdapat jamur dan bakteri pengurai. Banyak daun kering dan bangkai hewan menumpuk di tanah.<br>Apa akibat yang paling mungkin terjadi?', 'none', '', '["Semua tumbuhan langsung tumbuh lebih subur.", "Tidak ada lagi makhluk hidup yang membutuhkan makanan.", "Sisa makhluk hidup sulit terurai sehingga unsur hara tidak kembali ke tanah dengan baik.", "Semua hewan berubah menjadi pengurai."]'::jsonb, '[]'::jsonb, 'Tidak ada lagi makhluk hidup yang membutuhkan makanan.', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_29', 'PG', 'IPAS', 'Sekelompok peserta didik mengamati ekosistem sawah. Mereka menemukan padi, tikus, ular, dan elang.<br>Kelompok tersebut membuat empat diagram rantai makanan. Diagram yang paling tepat adalah ....', 'none', '', '["Tikus → Padi → Ular → Elang", "Padi → Tikus → Ular → Elang", "Elang → Ular → Tikus → Padi", "Ular → Elang → Padi → Tikus"]'::jsonb, '[]'::jsonb, 'Padi → Tikus → Ular → Elang', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261102_30', 'PG', 'IPAS', 'Di sebuah sawah, petani menggunakan racun secara berlebihan untuk membunuh semua ular karena dianggap mengganggu. Padahal, ular memakan tikus yang merusak tanaman padi.<br>Menurut pendapatmu, tindakan yang paling tepat untuk menjaga keseimbangan ekosistem sawah adalah ....', 'none', '', '["Membunuh semua hewan yang ada di sawah.", "Menggunakan racun sebanyak mungkin.", "Membiarkan tikus berkembang biak tanpa pengendalian.", "Menjaga keberadaan ular sebagai pemangsa alami tikus dan mengendalikan hama secara bijaksana."]'::jsonb, '[]'::jsonb, 'Menggunakan racun sebanyak mungkin.', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261105_01', 'PG', 'Bahasa Inggris SD', 'Perhatikan gambar berikut!<br>Apa kegiatan yang dilakukan anak pada gambar tersebut?', 'image', './assets/soal/soal-0004.jpg', '["Sleeping", "Reading", "Running", "Cooking"]'::jsonb, '[]'::jsonb, 'Reading', 10, 'Gambar menunjukkan seorang anak laki-laki sedang membaca buku (reading).'),
  ('Q_20261105_02', 'PG', 'Bahasa Inggris SD', 'Perhatikan gambar berikut!<br>Kata kerja <i>verb-ing</i><i> </i>yang sesuai dengan gambar adalah ....', 'image', './assets/soal/soal-0005.jpg', '["Eating", "Drinking", "Writing", "Swimming"]'::jsonb, '[]'::jsonb, 'Eating', 10, 'Gambar menunjukkan seorang anak sedang makan menggunakan sendok (eating).'),
  ('Q_20261105_03', 'PG', 'Bahasa Inggris SD', 'Bentuk <i>verb-ing</i><i> </i>yang tepat dari kata kerja <i>write</i><i> </i>adalah ....', 'none', '', '["Writeing", "Writting", "Writing", "Writed"]'::jsonb, '[]'::jsonb, 'Writing', 10, 'Kata kerja berakhiran huruf -e (write) menghilangkan huruf - e sebelum ditambah -ing menjadi writing.'),
  ('Q_20261105_04', 'PG', 'Bahasa Inggris SD', 'Bentuk <i>verb-ing</i><i> </i>dari kata kerja <i>swim</i><i> </i>adalah ....', 'none', '', '["Swimning", "Swimming", "Swimmed", "Swim"]'::jsonb, '[]'::jsonb, 'Swimming', 10, 'Kata kerja satu suku kata berpola konsonan-vokal-konsonan (swim) menggandakan konsonan terakhir menjadi swimming.'),
  ('Q_20261105_05', 'PG', 'Bahasa Inggris SD', '​Perhatikan kalimat berikut! &quot;My mother is cooking.&quot; Apa arti kalimat tersebut?', 'none', '', '["Ibu saya sedang memasak.", "Ibu saya sedang tidur.", "Ibu saya sedang membaca.", "Ibu saya sedang bermain."]'::jsonb, '[]'::jsonb, 'Ibu saya sedang memasak.', 10, 'My mother = ibu saya, is cooking = sedang memasak.'),
  ('Q_20261105_06', 'PG', 'Bahasa Inggris SD', 'Perhatikan gambar berikut!<br>Kalimat yang tepat untuk menggambarkan kegiatan pada gambar adalah ....', 'image', './assets/soal/soal-0006.jpg', '["She is sleeping.", "She is eating.", "She is sweeping.", "She is singing."]'::jsonb, '[]'::jsonb, 'She is sweeping.', 10, 'Gambar menunjukkan anak perempuan sedang menyapu lantai (sweeping).'),
  ('Q_20261105_07', 'PG', 'Bahasa Inggris SD', 'Lengkapilah kalimat berikut! &quot;They are	football in the field.&quot;', 'none', '', '["play", "plays", "playing", "played"]'::jsonb, '[]'::jsonb, 'playing', 10, 'Pola Present Continuous Tense: Subject + to be (are) + Verb-ing (playing).'),
  ('Q_20261105_08', 'PG', 'Bahasa Inggris SD', 'Perhatikan gambar berikut!<br>Kalimat yang tepat untuk menggambarkan aktivitas anak tersebut adalah ....', 'image', './assets/soal/soal-0007.jpg', '["He is eating.", "He is drinking.", "He is reading.", "He is running."]'::jsonb, '[]'::jsonb, 'He is drinking.', 10, 'Gambar menunjukkan anak laki-laki sedang minum air dari gelas (drinking).'),
  ('Q_20261105_09', 'PG', 'Bahasa Inggris SD', 'Angka 50 dalam Bahasa Inggris adalah ....', 'none', '', '["Fifteen", "Fifty", "Five", "Fifty one"]'::jsonb, '[]'::jsonb, 'Fifty', 10, 'Angka 50 dalam Bahasa Inggris adalah fifty (15 = fifteen).'),
  ('Q_20261105_10', 'PG', 'Bahasa Inggris SD', 'Bagaimana penulisan angka 65 dalam Bahasa Inggris?', 'none', '', '["Sixty five", "Sixteen five", "Fifty six", "Sixty five teen"]'::jsonb, '[]'::jsonb, 'Sixty five', 10, '60 = sixty, 5 = five, sehingga 65 ditulis sixty five.'),
  ('Q_20261105_11', 'PG', 'Bahasa Inggris SD', 'Angka <i>seventy</i><i> </i><i>eight</i><i> </i>jika ditulis dalam bentuk angka adalah ....', 'none', '', '["68", "87", "78", "77"]'::jsonb, '[]'::jsonb, '78', 10, 'Seventy = 70, eight = 8, sehingga seventy eight adalah 78.'),
  ('Q_20261105_12', 'PG', 'Bahasa Inggris SD', 'Angka setelah 89 adalah ....', 'none', '', '["Eighty eight", "Ninety", "Ninety one", "Seventy nine"]'::jsonb, '[]'::jsonb, 'Ninety', 10, 'Angka setelah 89 adalah 90, yang dalam Bahasa Inggris disebut ninety.'),
  ('Q_20261105_13', 'PG', 'Bahasa Inggris SD', 'Perhatikan gambar berikut!<br>Berapakah jumlah bintang yang ada pada gambar tersebut dalam Bahasa Inggris?', 'image', './assets/soal/soal-0008.jpg', '["Fifty", "Sixty", "Seventy", "Eighty"]'::jsonb, '[]'::jsonb, 'Seventy', 10, 'Terdapat 6 baris bintang dengan 12 bintang per baris (total 72 bintang). Pada pilihan jawaban yang tersedia, angka puluhan terdekat adalah Seventy (70).'),
  ('Q_20261105_14', 'PG', 'Bahasa Inggris SD', 'Di dalam sebuah kotak terdapat 100 pensil. Bahasa Inggris dari 100 adalah ....', 'none', '', '["Ninety", "Eighty", "One hundred", "One thousand"]'::jsonb, '[]'::jsonb, 'One hundred', 10, 'Angka 100 dalam Bahasa Inggris adalah one hundred (1.000
INSERT INTO public.cbt_questions (id, type, subject, text, media_type, media_url, options, pairs, answer, weight, explanation) VALUES
  ('Q_20261105_21', 'PG', 'Bahasa Inggris SD', 'Jika ruang makan berada <i>di</i><i> </i><i>belakang</i><i> </i>ruang tamu, bagaimana kalimat Bahasa Inggris yang tepat?', 'none', '', '["The dining room is <i>beside</i><i> </i>the living room.", "The dining room is <i>under</i><i> </i>the living room.", "The dining room is <i>behind</i><i> </i>the living room.", "The dining room is <i>in</i><i> </i>the living room."]'::jsonb, '[]'::jsonb, 'The dining room is <i>behind</i><i> </i>the living room.', 10, 'Dining room = ruang makan, behind = di belakang, living room = ruang tamu.'),
  ('Q_20261105_22', 'PG', 'Bahasa Inggris SD', 'Perhatikan kalimat berikut!<br>&quot;The bathroom is between the kitchen and the bedroom.&quot; Apa arti kata <i>between </i>pada kalimat tersebut?', 'none', '', '["Di depan", "Di belakang", "Di antara", "Di samping"]'::jsonb, '[]'::jsonb, 'Di antara', 10, 'Kata between berarti di antara.'),
  ('Q_20261105_23', 'PG', 'Bahasa Inggris SD', 'Arti ungkapan <i>every</i><i> </i><i>morning</i><i> </i>adalah ....', 'none', '', '["Setiap malam", "Setiap pagi", "Setiap sore", "Setiap minggu"]'::jsonb, '[]'::jsonb, 'Setiap pagi', 10, 'Every = setiap, morning = pagi.'),
  ('Q_20261105_24', 'PG', 'Bahasa Inggris SD', 'Bahasa Inggris dari kegiatan &quot;menyikat gigi&quot; adalah ....', 'none', '', '["Brush my teeth", "Wash my clothes", "Take a bath", "Make my bed"]'::jsonb, '[]'::jsonb, 'Brush my teeth', 10, 'Menyikat gigi dalam Bahasa Inggris adalah brush my teeth.'),
  ('Q_20261105_25', 'PG', 'Bahasa Inggris SD', 'Perhatikan kalimat berikut! &quot;I take a bath every morning.&quot; Apa arti kalimat tersebut?', 'none', '', '["Saya makan setiap pagi.", "Saya tidur setiap pagi.", "Saya mandi setiap pagi.", "Saya belajar setiap pagi."]'::jsonb, '[]'::jsonb, 'Saya mandi setiap pagi.', 10, 'Take a bath = mandi, every morning = setiap pagi.'),
  ('Q_20261105_26', 'PG', 'Bahasa Inggris SD', 'Perhatikan percakapan berikut!<br>Teacher: &quot;What do you do every morning?&quot; Student: &quot;.	&quot;<br>Jawaban yang tepat adalah ....', 'none', '', '["I am ten years old.", "I brush my teeth.", "My name is Andi.", "I like apples."]'::jsonb, '[]'::jsonb, 'I brush my teeth.', 10, 'Pertanyaan menanyakan kegiatan rutin setiap pagi (''What do you do every morning?''), jawaban yang sesuai adalah aktivitas pagi hari.'),
  ('Q_20261105_27', 'PG', 'Bahasa Inggris SD', 'Perhatikan kalimat berikut!<br>&quot;My father watches TV every night.&quot; Kapan ayah menonton televisi?', 'none', '', '["Every morning", "Every afternoon", "Every day", "Every night"]'::jsonb, '[]'::jsonb, 'Every night', 10, 'Berdasarkan kalimat ''My father watches TV every night'', ayah menonton TV setiap malam (every night).'),
