  ('Q_20261114_26', 'PG', 'Seni Budaya', '<b>Alfajrin</b><b> membuat gambar taman. Ia menggambar dua pohon dengan ukuran yang sama di sisi kiri dan kanan rumah. Susunan tersebut membuat gambar terlihat seimbang. Prinsip komposisi yang digunakan </b><b>Alfajrin</b><b> adalah ....</b>', 'none', '', '["asimetris", "simetris", "terpusat", "ritme"]'::jsonb, '[]'::jsonb, 'simetris', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261114_27', 'PG', 'Seni Budaya', '<b>Azzam</b><b> ingin membuat gambar hiasan dengan pola daun yang berulang. Namun, ia menggambar daun dengan jarak yang tidak teratur sehingga hasilnya terlihat kurang rapi. Hal yang sebaiknya dilakukan </b><b>Azzam</b><b> adalah ....</b>', 'none', '', '["menghapus seluruh gambar dan menggantinya dengan warna hitam", "memperbesar semua gambar daun", "mengatur pengulangan bentuk dan jarak daun secara teratur", "menggambar daun dengan bentuk berbeda-beda tanpa pola"]'::jsonb, '[]'::jsonb, 'mengatur pengulangan bentuk dan jarak daun secara teratur', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261114_28', 'PG', 'Seni Budaya', '<b>Fadil</b><b> ingin menggambar sebuah meja dan gelas yang berada di atasnya. Ia menggambar gelas lebih besar daripada meja sehingga terlihat tidak sesuai dengan keadaan sebenarnya. Kesalahan yang dilakukan </b><b>Fadil</b><b> berkaitan dengan prinsip ....</b>', 'none', '', '["ritme", "proporsi", "tekstur", "warna"]'::jsonb, '[]'::jsonb, 'proporsi', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261114_29', 'PG', 'Seni Budaya', '<b>Riswan</b><b> ingin membuat gantungan pot tanaman menggunakan teknik makrame. Ia memiliki tali katun, gunting, manik-manik, dan penggaris. Agar dapat menghasilkan karya yang kuat dan menarik, tindakan yang paling tepat adalah ....</b>', 'none', '', '["memotong tali tanpa mengukur panjangnya", "mengikat tali secara sembarangan tanpa pola", "mengukur tali, membuat simpul dengan benar, dan menambahkan hiasan seperlunya", "menempelkan semua tali menggunakan cat air"]'::jsonb, '[]'::jsonb, 'mengukur tali, membuat simpul dengan benar, dan menambahkan hiasan seperlunya', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261114_30', 'PG', 'Seni Budaya', 'Kelompok siswa <b>SD</b><b> membuat hiasan dinding dari tali. Hasil karya mereka terlihat kurang rapi karena simpul yang dibuat tidak sama dan jarak antarbagian tidak teratur. Agar hasil karya menjadi lebih baik, mereka sebaiknya ....</b>', 'none', '', '["menggunakan tali sebanyak mungkin", "memperbaiki susunan simpul dan mengatur jarak setiap bagian dengan teratur", "mengganti semua tali dengan kertas", "menambahkan warna sebanyak-banyaknya tanpa memperbaiki simpul<br><b>SELAMAT MENGERJAKAN!</b><br>Jadilah siswa yang kreatif, teliti, dan selalu semangat berkarya."]'::jsonb, '[]'::jsonb, 'memperbaiki susunan simpul dan mengatur jarak setiap bagian dengan teratur', 10, 'Sesuai kunci jawaban.'),
  ('Q_20261116_01', 'PG', 'Bahasa Indonesia SD', 'Kata sifat adalah kata yang digunakan untuk ....', 'none', '', '["menunjukkan nama orang", "menerangkan sifat atau keadaan", "menyatakan kegiatan", "menunjukkan tempat"]'::jsonb, '[]'::jsonb, 'menerangkan sifat atau keadaan', 10, 'Sesuai kunci jawaban.')
